{
  Clean();
}


/**-------------------------------------------------------------------------------------------------------------------
* 
* @fn         XASN1::~XASN1()
* @brief      Destructor of class
* @note       VIRTUAL
* @ingroup    XUTILS
* 
* --------------------------------------------------------------------------------------------------------------------*/
XASN1::~XASN1()
{
  Clean();
}


/**-------------------------------------------------------------------------------------------------------------------
* 
* @fn         XASN1_OID_PROPERTY* XASN1::GetOIDProperty(XCHAR* OID)
* @brief      Get OID property
* @ingroup    XUTILS
* 
* @param[in]  OID : OID pointer to use.
* 
* @return     XASN1_OID_PROPERTY* : Pointer to the requested object; NULL if it is not available.
* 
* --------------------------------------------------------------------------------------------------------------------*/
XASN1_OID_PROPERTY* XASN1::GetOIDProperty(XCHAR* OID)
{
  XSTRING _OID = OID;

  for(XDWORD c=0; c<(sizeof(OID_properties)/sizeof(XASN1_OID_PROPERTY)); c++)
    {
      if(!_OID.Compare(OID_properties[c].OID, true))
        {
          return &OID_properties[c];
        }
    }

  return NULL;
}


/**-------------------------------------------------------------------------------------------------------------------
* 
* @fn         XCHAR* XASN1::GetOIDPropertyDescription(XCHAR* OID)
* @brief      Get OID property description
* @ingroup    XUTILS
* 
* @param[in]  OID : OID pointer to use.
* 
* @return     XCHAR* : Pointer to the requested object; NULL if it is not available.
* 
* --------------------------------------------------------------------------------------------------------------------*/
XCHAR* XASN1::GetOIDPropertyDescription(XCHAR* OID)
{
  XSTRING _OID = OID;

  for(XDWORD c=0; c<(sizeof(OID_properties)/sizeof(XASN1_OID_PROPERTY)); c++)
    {
      if(!_OID.Compare(OID_properties[c].OID, true))
        {
          return OID_properties[c].description;
        }
    }

  return NULL;
}


/**-------------------------------------------------------------------------------------------------------------------
* 
* @fn         bool XASN1::Decode(XBUFFER& databin, XOBSERVER* observer)
* @brief      Decode
* @ingroup    XUTILS
* 
* @param[in]  databin : Databin value.
* @param[in]  observer : Observer pointer to use.
* 
* @return     bool : true if the operation is successful; otherwise false.
* 
* --------------------------------------------------------------------------------------------------------------------*/
bool XASN1::Decode(XBUFFER& databin, XOBSERVER* observer)
{
  bool status = true;

  if(!databin.GetSize()) 
    {
      return false;
    }

   XBER ber; 

   if(!ber.SetFromDump(databin, observer))
    {      
      status = false;
    }

  return status;
}


